name: deploy

on:
  push:
    branches: [main]
  pull_request:
    paths: [infra/**, .github/workflows/deploy.yml]
  workflow_dispatch:

concurrency:
  group: ${{ github.event_name == 'pull_request' && format('infra-plan-{0}', github.ref) || 'smoke' }}
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  infra:
    if: github.event_name == 'pull_request'
    runs-on: ubuntu-latest
    env:
      CLOUDFLARE_API_TOKEN: ${{ secrets.CLOUDFLARE_API_TOKEN }}
      TF_IN_AUTOMATION: "1"
    defaults:
      run:
        working-directory: infra
    steps:
      - uses: actions/checkout@v5
        with:
          ref: ${{ github.event.pull_request.head.sha }}
      - uses: opentofu/setup-opentofu@v2
        with:
          tofu_version: 1.12.6
          tofu_wrapper: false
      - run: tofu init -input=false
      - run: tofu plan -input=false -lock=false

  smoke:
    if: github.event_name != 'pull_request'
    runs-on: ubuntu-latest
    timeout-minutes: 30
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
          cache: npm
      - run: npm ci
      - run: npx playwright install --with-deps chromium-headless-shell
      - name: Read the Access service token from the committed state
        run: |
          output() {
            node -e 'process.stdout.write(JSON.parse(require("fs").readFileSync(process.argv[1], "utf8")).outputs[process.argv[2]].value)' infra/terraform.tfstate "$1"
          }
          id="$(output access_client_id)"
          secret="$(output access_client_secret)"
          echo "::add-mask::$id"
          echo "::add-mask::$secret"
          {
            echo "CF_ACCESS_CLIENT_ID=$id"
            echo "CF_ACCESS_CLIENT_SECRET=$secret"
          } >> "$GITHUB_ENV"
      - name: Wait for Workers Builds to serve this commit
        run: npm run wait:live -- "$GITHUB_SHA"
      - name: Smoke through Access
        run: npm run smoke -- "https://stallion.matthijs-f49.workers.dev/b/ci-${{ github.run_id }}"
#!/bin/sh
set -eu

cd "$(dirname "$0")/.."

cargo_bin="${CARGO_HOME:-$HOME/.cargo}/bin"
PATH="$cargo_bin:$PATH"
export PATH

if ! command -v rustup >/dev/null 2>&1; then
  curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs |
    sh -s -- -y --profile minimal --default-toolchain none --no-modify-path
fi

rustup toolchain install

if ! command -v worker-build >/dev/null 2>&1; then
  cargo install --locked worker-build@^0.8
fi

cd crates/server
exec worker-build --release
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

if (process.env.WORKERS_CI !== "1") {
  console.error(
    "npm run deploy runs only inside Cloudflare Workers Builds; push to main to deploy",
  );
  process.exit(1);
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const state = JSON.parse(readFileSync(join(root, "infra", "terraform.tfstate"), "utf8"));
const output = (name) => {
  const value = state.outputs?.[name]?.value;
  if (!value) {
    console.error(`infra/terraform.tfstate has no ${name} output; run npm run infra:apply`);
    process.exit(1);
  }
  return value;
};

const run = spawnSync(
  "npx",
  [
    "wrangler",
    "deploy",
    "--var",
    `ACCESS_TEAM_DOMAIN:${output("access_team_domain")}`,
    "--var",
    `ACCESS_AUD:${output("access_aud")}`,
  ],
  { cwd: root, stdio: "inherit" },
);
if (run.error) throw run.error;
process.exit(run.status ?? 1);
import { accessHeaders } from "./env.mjs";

const [commit, origin = "https://stallion.matthijs-f49.workers.dev"] = process.argv.slice(2);
if (!commit) {
  console.error("usage: node npm-scripts/wait-live.mjs <commit sha> [origin]");
  process.exit(2);
}

const TIMEOUT_MS = 15 * 60_000;
const INTERVAL_MS = 20_000;
const probe = new URL("/api/me/boards", origin);
const deadline = Date.now() + TIMEOUT_MS;
let live = "";

while (Date.now() < deadline) {
  const response = await fetch(probe, { headers: accessHeaders(), redirect: "manual" }).catch(
    (error) => {
      console.log(`${probe} failed: ${error.message}`);
      return undefined;
    },
  );
  live = response?.headers.get("x-stallion-commit") ?? "";
  if (live === commit) {
    console.log(`${origin} serves ${commit}`);
    process.exit(0);
  }
  console.log(
    `${origin} serves ${live || "no x-stallion-commit"} (status ${response?.status}); waiting for ${commit}`,
  );
  await new Promise((resolve) => setTimeout(resolve, INTERVAL_MS));
}

console.error(
  `${origin} still serves ${live || "no x-stallion-commit"} after 15 minutes, not ${commit}; check the Workers Builds log for the stallion Worker`,
);
process.exit(1);
