const ACC = "f496802dcadb597e5939f6449c759a43";
export async function cf(path, init = {}) {
  const r = await fetch(`https://api.cloudflare.com/client/v4/accounts/${ACC}${path}`, {
    ...init,
    headers: { Authorization: `Bearer ${token}`, "Content-Type": "application/json", ...(init.headers ?? {}) },
  });
  const text = await r.text();
  let body; try { body = JSON.parse(text); } catch { body = text; }
  return { status: r.status, body };
}
export const accessHeaders = () => ({ "CF-Access-Client-Id": env.CF_ACCESS_CLIENT_ID, "CF-Access-Client-Secret": env.CF_ACCESS_CLIENT_SECRET });
export const keys = Object.keys(env);
export { redact };
